const m=read(c.modelOutput+'/engine-signals.json'),defenseSignals={centers:m.centers,values:Object.fromEntries(m.players.map((p,i)=>[p,Object.fromEntries(Object.entries(m.effects).map(([z,v])=>[z,v[i]]))]))},stats=table(c.paths['data/season-source/team-games.json']).filter(r=>train.has(r.GAME_ID)),sum=z=>stats.reduce((s,r)=>s+r[z],0),globalShare=overall[0]/overall[1];
