const options={...NBA_DEFENSE_V1,seasonMinuteTargets:true,reboundAccounting:true,reboundProfile:false,reboundRates,stealPriorRate:league.priorRate,empiricalTiming:true,continuousTiming:true,independentClock:true,clockViolationProbability:clock/eligible,timingCDF:timing,foulOutcomes:true,relativeFouls:true,foulRates:fouls,leagueFTR:sum('FTA')/sum('FGA'),foulProfileMeans:read(c.foulMeansOutput)['pre'+c.k],turnoverCategories:true,deadCategoryWeights:['offensiveFoul','otherViolation','passing','handling','outOfBoundsUnclassified'].map(z=>groups[z]?.dead??0),pace:1,foulScale:1,passTurnoverScale:1,touchTurnoverScale:1,touchLiveShare:(groups.handling?.live??0)/Math.max(1,groups.handling?.count??0),reboundSignal:true,rimSignal:true,liveSignal:true,zoneSignal:true,foulSignal:true,defenseSignals,rotationCurve};
const bundle={league,exposure:read(c.exposure),options,season:c.season,date:c.date,trainGames:c.trainGames,sourceConfig:hash(process.argv[2]),measured:{turnoverGroups:groups,reboundRates,fouls,eligibleClockPossessions:eligible,clockViolations:clock}};
